private async fetchStory(storyId) {
  const f = await this.fetchWorkItemFields(storyId);
  return {
    id: storyId,
    title: f['System.Title'] || '',
    state: f['System.State'] || '',
    description: cleanHtml(f['System.Description'] || ''), // ADO rich-text fields are HTML; cleanHtml flattens to plain text the model can read
    acceptanceCriteria: cleanHtml(f['Microsoft.VSTS.Common.AcceptanceCriteria'] || ''), // this is the ORIGINAL AC, read once and never written back — the agent is additive
    parentId: String(f['System.Parent'] || ''), // stringified for consistent downstream use; empty string when the story has no parent
    adoUrl: `https://dev.azure.com/my-org/MyProject/_workitems/edit/${storyId}`, // deep link kept so every refined criterion can cite its source ticket
  };
}

function loadStoryIntelligence(storyId) {
  const intelPath = findIntelligenceFile(storyId);
  if (!intelPath) return { found: false, businessRules: [], userFlowSteps: [] }; // no prior briefing found — return a valid empty shape (found:false) rather than throwing

  const raw = JSON.parse(fs.readFileSync(intelPath, 'utf-8'));
  const rules = (raw.businessRules || [])
    .map(r => r.description || r.name || (typeof r === 'string' ? r : '')) // rules arrive in mixed shapes ({description}, {name}, or bare string) — normalize each to text
    .filter(r => r && r.length > 10) // drop empties and trivially short fragments that add no signal
    .slice(0, 10); // cap at 10 rules to bound the prompt size fed to the multimodal model

  return {
    storyTitle: raw.storyTitle || raw.title || '',
    summary: (raw.summary || '').slice(0, 800), // summary trimmed to 800 chars — enough context without crowding out the design images
    businessRules: rules,
    found: true,
    intelPath,
  };
}

function loadFigmaContext(figmaDir, includeImages) {
  const framesJsonText = fs.existsSync(framesPath)
    ? fs.readFileSync(framesPath, 'utf-8').slice(0, 20000) : ''; // 20k-char cap on the frame JSON — a token-budget guard; absent file => empty string, not a throw
  const textContentMd = fs.existsSync(textPath)
    ? fs.readFileSync(textPath, 'utf-8').slice(0, 15000) : ''; // on-screen text listing capped at 15k chars

  const images = [];
  if (includeImages && fs.existsSync(screensDir)) { // images are opt-in (--no-images clears includeImages) and skipped if the screens folder is missing
    const pngs = fs.readdirSync(screensDir)
      .filter(f => /\.(png|jpg|jpeg)$/i.test(f)).sort().slice(0, MAX_DESIGN_IMAGES);
    for (const filename of pngs) {
      const buf = fs.readFileSync(path.join(screensDir, filename));
      images.push({ filename, mimeType: 'image/png', base64: buf.toString('base64') }); // base64-encode each screenshot for inline transport in the multimodal request
    }
  }
  return { framesJsonText, textContentMd, images, imageCount: images.length }; // imageCount is recorded so the result can report how many screens actually grounded the criteria
}

async function callGeminiMultimodal(systemText, userText, images, options) {
  const parts = [{ text: systemText + '\n\n' + userText }];

  for (const img of images) {
    parts.push({ inlineData: { mimeType: img.mimeType, data: img.base64 } }); // each screenshot rides inline as an inlineData part — Gemini reads the pixels, not a description
    parts.push({ text: `[Design image attached above: ${img.filename}]` }); // a text marker after each image so the model can name which screen a criterion came from
  }

  const response = await fetch(GEMINI_URL, {
    method: 'POST',
    body: JSON.stringify({
      contents: [{ parts }],
      generationConfig: { maxOutputTokens: options?.maxTokens ?? 8192, temperature: options?.temperature ?? 0.2 }, // temp 0.2: criteria must quote exact on-screen text, not paraphrase; ?? sets the defaults
    }),
  });

  const data = await response.json();
  return { answer: data.candidates?.[0]?.content?.parts?.[0]?.text || '', model: 'gemini-2.0-flash' }; // deep optional-chaining: a blocked/empty candidate yields '' instead of a crash
}

private async buildExcel(results, ts) {
  const ws = wb.addWorksheet('Refined AC');
  ws.columns = [
    { header: 'Story ID', key: 'storyId', width: 10 },
    { header: 'AC #', key: 'acId', width: 8 },
    { header: 'Given', key: 'given', width: 40 },
    { header: 'When', key: 'when', width: 40 },
    { header: 'Then', key: 'then', width: 40 },
    { header: 'Design Refs', key: 'designs', width: 40 }, // the citations — which screens each criterion was grounded in
  ];

  for (const r of results) { // flatten: nested refinedAC arrays become one worksheet row PER criterion
    for (const ac of r.refinedAC) { // one row per AC — the grain ADO import expects, not one row per story
      ws.addRow({ storyId: r.storyId, acId: ac.id, given: ac.given, when: ac.when,
        then: ac.then, designs: (ac.designReferences || []).join('\n') });
    }
  }

  const xlsxPath = path.join(this.outputDir, `StoryAC_Refinement_${ts}.xlsx`);
  await wb.xlsx.writeFile(xlsxPath); // write the workbook; the paste-back-into-ADO deliverable
  return xlsxPath;
}
